head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL15301";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15301.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return (dma_pageContext.get("lawTitle") ?? ""); } },
        { childId: "__rb1", fn: function () { return "개정일 : " + String((dma_pageContext.get("lawAmendDd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil15301: 진입 키 poplaw 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_lawItemList_2_oncellclick
 * @description grd_lawItemList_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lawItemList_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawItemList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lawItemList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["lawItmStepTpNo"] === 4) { await scwin.lawItemView(r["lawItmSeq"]); return; }
        await scwin.viewAddRule(); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawItemList_2.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_LawItemView
 * @description Law Item View 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_LawItemView = async function (action) {
    const sbmOptions = {
        id: "tx_fn_LawItemView",
        method: "post",
        action: action ?? "/support/popLaw.do",
        ref: "dma_LawItemViewReq",
        target: "dlt_lawItemList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ViewAddRule
 * @description View Add Rule 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewAddRule = async function (action) {
    const sbmOptions = {
        id: "tx_fn_ViewAddRule",
        method: "post",
        action: action ?? "/support/popLaw.do",
        ref: "dma_ViewAddRuleReq",
        target: "dlt_lawItemList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name lawItemView
 * @description law Item View 처리
 * @param {*} _lawItmSeq _lawItmSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.lawItemView = async function (_lawItmSeq) {
    let action;
    $c.util.getComponent('dma_LawItemViewReq').set('lawItmSeq', _lawItmSeq);
    $c.util.getComponent('dma_LawItemViewReq').set('method', "viewLawItemTemplete");
    action = "popLaw.do";
    $c.win.openPopup("", { id: "viewLawItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    const nr = await scwin.tx_fn_LawItemView(action);
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL15302.xml", { "lawItmSeq": _lawItmSeq, "method": "viewLawItemTemplete" });
    }
};

/**
 * @method
 * @name viewAddRule
 * @description view Add Rule 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewAddRule = async function () {
    let action;
    $c.util.getComponent('dma_LawItemViewReq').set('method', "viewAddRule");
    action = "popLaw.do";
    $c.win.openPopup("", { id: "viewLawItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    const nr = await scwin.tx_fn_ViewAddRule(action);
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL15304.xml", { "method": "viewAddRule" });
    }
};
